def transforms(S):
  for k in range(4):
    for refl in [False,True]:
      pts=[]
      for r,c in S:
        x,y=r,c
        if refl:y=-y
        for _ in range(k): x,y=y,-x
        pts.append((x,y))
      mr=min(x for x,y in pts); mc=min(y for x,y in pts)
      yield k,refl,{(x-mr,y-mc) for x,y in pts}
for t,r,s in transforms(A):
